peers = [
dict(name='Tally Docs by Ira',scope='Direct competitor: Indian Tally invoice entry',facts='Reads documents into draft vouchers; maps masters; user reviews before posting.',architecture='FAQ documents master matching and saved mappings. Underlying model/framework stack is not disclosed in the reviewed sources.',lesson='OCR-to-voucher is already a native product category. Compete on measured reduction in review effort, not feature novelty.',limit='FAQ lists English invoices and one transaction per file; source quality/layout issues can require correction. Eligibility depends on license/TSS/release.',refs=['tally','ira']),
dict(name='AI Accountant / KoreFi',scope='Direct competitor: automation alongside Tally',facts='Advertises bank/bill ingestion, transaction mapping and approved sync into Tally.',architecture='Public setup requires a connector on the Tally computer and company synchronisation. Specific OCR/agent framework is unverified.',lesson='A local connector is a normal deployment component. Strong ingestion and ledger mapping matter more than chat alone.',limit='Published handwriting accuracy and time savings are vendor claims; this research did not run a trial.',refs=['aia','aia-connect']),
dict(name='Dext',scope='Adjacent benchmark: document bookkeeping',facts='Admin supplier rules reuse recurring defaults; documented duplicate matching uses extracted identity/reference/amount fields.',architecture='Public help describes rule precedence and exceptions; it does not establish that Dext uses LangGraph or a particular LLM.',lesson='Explicit business memory is useful even without training. Store approved mappings separately from suggestions.',limit='Integration- and plan-specific behaviour; no Tally compatibility claim established here.',refs=['dext','duplicates']),
dict(name='Vic.ai',scope='Adjacent benchmark: enterprise AP autonomy',facts='Document interpretation and coding, configurable review thresholds and optional touchless workflows.',architecture='API exposes master/history synchronisation and ERP webhooks. Trust center distinguishes global header models from customer-specific coding models.',lesson='Synchronised accounting context + correction feedback + controlled autonomy is the pattern to copy. Their private training corpus is not available to Philixa.',limit='Enterprise integrations and proprietary models are not a drop-in local stack. Claimed accuracy was not independently reproduced.',refs=['vic','vic-api','vic-models']),
dict(name='Docsumo',scope='Adjacent benchmark: intelligent document processing',facts='Describes an intake → classify → extract → validate → exceptions → ERP flow.',architecture='Public product describes vendor/PO/math/duplicate checks, source highlighting, APIs and webhooks. Internal agent implementation is undisclosed.',lesson='Make the exception the unit of user work. A single uncertain cell should not require retyping the entire bill.',limit='Published field accuracy/touchless rates depend on workload; they do not prove Indian GST end-to-end correctness.',refs=['docsumo']),
]
stack = [
['API / business state','Keep FastAPI + Pydantic + SQLAlchemy + PostgreSQL','Typed draft/action/evidence contracts and workspace/company scoping. PostgreSQL remains accounting workflow truth.','Existing stack; no rewrite'],
['Agent control','LangGraph + PostgreSQL checkpointer','Bounded planner → permitted reads → draft → deterministic checks → exception/review → authorised action → verification. Keep side effects outside replayable model steps.','Add persistence and evidence loop; current graph is routing'],
['Chat understanding','Existing Groq GPT-OSS 20B baseline; benchmark 120B','Extract several explicit details from one message, with source spans. Use strict schema extraction separately from the tool-calling stage. Neither JSON validity nor a larger model proves factual correctness.','Baseline + challenger; no global best claim'],
['Accounting context','Scoped SQL read models + native Tally sync','Index native company/master IDs, effective dates, supplier-item history and existing invoices. Every returned value carries source/time/revision. Refresh stale/missing data before decisive use.','Highest-priority missing capability'],
['Document pipeline','PyMuPDF + one isolated layout/table parser','Reuse digital text. Compare Docling or PP-StructureV3 with existing RapidOCR on the same corpus. Do not install all engines in the request path.','CPU-conscious first experiment'],
['Photo / hard-layout challenger','PaddleOCR-VL-1.6 OR capped Mistral OCR 4.1 test','VL local fit is hardware-dependent. Mistral offers structured annotations but sends data externally and incurs API cost. Azure/Google are procurement alternatives, not mandatory additions.','Choose by measured whole-bill results'],
['Accounting decisions','Python Decimal + deterministic policy/evidence checks','Identity, date/reference, duplicates, tax and totals must be checked independently of model prose. A confidence number never authorises a write.','Reuse and extend existing validators'],
['Work / integration','ARQ + Redis + durable PostgreSQL outbox + paired Windows helper','Resume background work; retain action-specific identity, SQLite journal and Tally read-back reconciliation. MCP may wrap permitted tools; it adds no intelligence or accuracy by itself.','Keep; Temporal only if operational need justifies migration'],
['User experience / evidence','Existing JS UI + concise review card + exception queue','Chat accepts the task; background tools do the work. Show material suggestions and unresolved questions together. Full fields remain available on demand.','Improve behaviour, not just hide fields'],
['Evaluation / tracing','Existing metrics + golden tests; optional Promptfoo/Langfuse','Track exact whole-bill correctness, unsafe auto-posts, review corrections/time, latency and cost. Keep accounting audit separate from model traces.','Measure before model replacement'],
]
gaps = [
('No durable graph checkpoint','app/services/portfolio_copilot_service.py: build_workflow returns graph.compile() without checkpointer; business tools route to END.','Add thread-scoped checkpoints and bounded evidence/validation loop; preserve outbox authority.'),
('JSON-object mode is not strict schema mode','app/ai/provider.py: Groq generate_json sends response_format=json_object; schema is only in a prompt.','Adopt provider-compatible strict schemas and refusal/error handling, with a separate tool stage.'),
('History is incomplete','app/services/purchase_context.py: only Philixa-verified draft/action pairs, max 100 updated drafts, 180-day window.','Read/sync native Tally purchase history with stable identity, dates and query filters; do not claim all-data analysis today.'),
('Photo parsing depends on layout rules','app/services/local_invoice_ocr.py and local_retail_invoice.py use token/header/layout logic.','Measure a layout/document-understanding adapter on different templates rather than accumulating one-off layouts.'),
('Review burden remains','purchase_conversation.py still chooses successive missing fields; collapsed UI does not eliminate missing data.','Parse multi-field messages; materialise a single editable proposal and group only genuine exceptions.'),
]
sections = [
('Decision','Best fit for Philixa is a controlled accounting agent over synchronised business data, not a bigger chatbot. Keep the current backend, add reliable context tools and a durable evidence loop, then benchmark one document-understanding upgrade. This is a project-specific engineering recommendation, not a claim that one universal best stack exists.'),
('What peers actually do','The recurring public pattern is ingestion, structured extraction, master/history matching, deterministic/business checks, exception routing and an ERP connector. Some vendors use proprietary training; others expose rules and approved mappings. These sources do not prove that competitors use LangGraph, Groq, PaddleOCR or our proposed stack.'),
('Bill-free chat','For “Sharma se 50 Cement bags liye”, read the selected company, approved supplier/item identity, unit, effective tax configuration, recent matching purchases and duplicate evidence. Historical rate is a labelled proposal, not evidence of today’s actual rate. Offer one review of material assumptions. If no source contains invoice reference/date or transaction facts, ask for those together; no technology can recover facts that were never supplied or recorded.'),
('Evidence contract','Every field should carry value, source type, native/source identity, source date, observed_at, draft revision and confirmed/proposed/unresolved status. Precedence: explicit current user correction or source evidence, validated effective masters for master facts, approved alias for identity, history for suggestions. Contradictions create an exception; they must not silently overwrite current evidence. Retrieval must enforce workspace/company permissions server-side.'),
('Memory without training','Use relational memory for supplier IDs, item IDs, effective master versions and approved aliases. Exact keys first; fuzzy/embedding search only proposes candidates. Do not feed all database rows into every prompt or allow unrestricted model-generated SQL. pgvector can later help semantic document search; it is not needed to compute balances, choose tax ledgers or identify duplicates.'),
('Autonomy boundary','Read tools can gather evidence within permission scopes. Validation issues route to review/block. Posting requires a specific reviewed action or an enabled durable policy, rechecked at dispatch. Graph checkpoints help resume reasoning; action identity/outbox/helper journal prevent blind re-posting. Closed Tally/PC means stale cached reads and queued work, not a live connection to a stopped accounting application.'),
('Deployment','Keep the paired outbound connector for customer PCs. Official Tally XML/JSON/ODBC routes exist; WebSocket bridging is a documented reference pattern, not a Tally-hosted service. A protocol migration should be separately certified against supported releases. ngrok is a temporary demo exposure, not persistent product hosting; a stable HTTPS backend and managed secrets/backup/update process are later pilot deployment work.'),
('What not to add now','No custom foundation-model training, mandatory vector database, multiple autonomous agents, simultaneous OCR vendors, Kubernetes or Temporal migration just to claim intelligence. Temporal is a credible durable workflow alternative when long-running orchestration justifies its operational cost; it does not remove connector idempotency requirements.'),
('Accuracy and release','Measure extraction, entity mapping, accounting and native posting separately, then end-to-end. Retain unreadable/unsupported cases in denominators. Split every copy of a bill together to prevent leakage. Existing project gate requires 200 accountant-labelled representative real invoices including 100 held-out, zero observed critical errors in eligible auto-post cases, plus measured review-inclusive handling time. These are project rollout requirements, not proof or a universal guarantee; real-world accuracy remains unverified.'),
('Execution order','1. Establish a frozen chat+bill baseline with expected outcomes. 2. Build native Tally context tools/read models and field provenance. 3. Add multi-field understanding and a compact proposal. 4. Add checkpoints and bounded tool/validation loop. 5. Compare one local document parser and an optional paid challenger under identical tests. 6. Run shadow mode and accountant evaluation before controlled posting rollout.'),
('Positioning','Say: Philixa is being built to reduce the work between a task and a verified Tally result. Do not claim unique OCR, fully automatic accounting, 100% accuracy or 50% savings yet. Clarify with an accountant which workflow causes the most repeated corrections; prove handling time against the same workload including review and failures.'),
]
refs_by_section={'What peers actually do':['tally','vic-api','dext','docsumo'], 'Memory without training':['dext','duplicates'],
 'Autonomy boundary':['graph','vic','aia-connect'], 'Deployment':['tally-api','bridge'], 'What not to add now':['temporal'],
 'Decision':['graph'],'Bill-free chat':[],'Evidence contract':[],'Accuracy and release':['eval','promptfoo'],'Execution order':[], 'Positioning':['ira']}
data=dict(date='28 October 2026 · IST',sources=sources,peers=peers,stack=stack,gaps=gaps,sections=sections)
(OUT/'research.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
e=html.escape
def links(keys):
    return ' · '.join(f'<a href="{e(s[2])}">{e(s[1])}</a>' for k in keys for s in sources if s[0]==k)
def table(headers, rows):
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
body='<header><p class="eyebrow">RESEARCH / 28 OCTOBER 2026 / INDIA</p><h1>Philixa: build the work engine behind the chat</h1><p class="lead">Best-fit stack, competitor evidence and the gaps in the current app.</p><p>Research completed from official public documentation and current local source. No vendor trial or new accuracy benchmark was run. Application code/configuration was not changed by this research.</p></header>'
body+='<nav><a href="#overview">Overview</a><a href="#competitors">Competitors</a><a href="#guidance">Guidance</a><a href="#sources">Sources</a></nav>'
body+='<section id="overview"><h2>Overview</h2><p class="lead">'+e(sections[0][1])+'</p><p><strong>Facts versus inference:</strong> product capabilities below are documented by vendors. Proposed stack choices are our engineering judgement. Private competitor model/framework details remain unknown unless explicitly disclosed.</p>'
body+='<h3>Current Philixa source audit</h3>'+table(['Finding','Current evidence','Required improvement'],gaps)+'</section>'
body+='<section id="competitors"><h2>Competitors</h2>'
for p in peers:
    body+='<article><h3>'+e(p['name'])+'</h3><p class="muted">'+e(p['scope'])+'</p>'
    for title,key in [('Published capability','facts'),('Public architecture evidence','architecture'),('Philixa implication — inference','lesson'),('Limits / do not overclaim','limit')]:
        body+='<p><strong>'+title+':</strong> '+e(p[key])+'</p>'
    body+='<p class="sources">'+links(p['refs'])+'</p></article>'
body+='<p>Additional adjacent signal: Intuit describes categorisation/reconciliation with approval/attention routing. It is not evidence of Tally compatibility. '+links(['intuit'])+'</p></section>'
body+='<section id="guidance"><h2>Guidance</h2><h3>Stack decision</h3>'+table(['Layer','Recommendation','Why / trade-off','Status'],stack)
body+='<p class="sources">'+links(['graph','groq','tools','models','paddle','structure','docling','mistral','annotations','azure','google','temporal','eval','promptfoo'])+'</p>'
body+='<h3>Cost reality — illustrative, not a bill</h3><p>Mistral lists $4 per 1,000 OCR pages or $5 per 1,000 annotated pages. At the annotated rate, 100 single-page documents cost $0.50 for that service, assuming one pass and standard listed pricing. Other model calls, retries, taxes, storage and hosting are additional.</p>'
body+='<p>Groq lists GPT-OSS 20B at $0.075 input / $0.30 output and 120B at $0.15 input / $0.60 output per million tokens. At an assumed 2,000 input + 500 output tokens per call, 1,000 calls would be $0.30 or $0.60 respectively. This is arithmetic from list prices, not measured Philixa usage or a free-tier promise. A multi-step task can involve several calls. Local OCR has no per-page external API charge, but consumes hardware, memory, power and maintenance.</p><p>'+links(['mistral','models'])+'</p>'
body+='<h3>Important provider constraint</h3><p>Groq documentation currently excludes tool use and streaming from Structured Outputs. Plan separate stages: strict field extraction → application-controlled tool calls → validated proposal. Schema compliance proves shape, not correct supplier, amount or transaction facts. '+links(['groq','tools'])+'</p>'
for title,text in sections[1:]:
    body+='<h3>'+e(title)+'</h3><p>'+e(text)+'</p>'
    if refs_by_section.get(title):body+='<p class="sources">'+links(refs_by_section[title])+'</p>'
body+='</section><section id="sources"><h2>Sources and evidence limits</h2><p>Accessed 28 October 2026. Official pages are first-party descriptions; vendor accuracy, customer outcomes and scale claims are not independent validation. Published capabilities are not proof of our implementation. This is a focused architectural comparison, not an exhaustive model leaderboard.</p>'
body+='<p>Evidence lanes used: user-provided workflow/screenshots, local project source/status documents, official public vendor and developer documentation. CRM, internal messaging, private competitor code and accountant interviews were not relevant/available evidence for this comparison; no external communications or account changes were made.</p><ol>'
for key,title,url,note in sources:body+='<li id="src-'+key+'"><a href="'+e(url)+'">'+e(title)+'</a><p>'+e(note)+'</p></li>'
body+='</ol><h3>Local evidence inspected</h3><p>requirements.txt; requirements-local-ocr.txt; app/services/portfolio_copilot_service.py; app/ai/provider.py; app/services/purchase_context.py; app/services/purchase_conversation.py; app/services/local_invoice_ocr.py; REAL_AUTOMATION_GATE.md; DAY_9_STATUS.md. This source audit is not a fresh live acceptance run.</p></section>'
css='''body{margin:0;background:#f7f7f5;color:#202825;font:16px/1.65 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:36px 28px}header{max-width:880px;padding:8px 0 24px}h1{font-size:32px;line-height:1.25;margin:12px 0}h2{font-size:25px;margin:0 0 18px}h3{font-size:19px;margin:28px 0 8px}.lead{font-size:19px}.eyebrow,.muted,.sources{color:#59645e}.eyebrow{font-size:12px;letter-spacing:.1em}nav{display:flex;gap:24px;flex-wrap:wrap;padding:16px 0;border-block:1px solid #cfd6d1}a{color:#1a6250;text-underline-offset:3px}section{padding:32px 0;border-bottom:1px solid #cfd6d1}article{padding:10px 0 20px;border-bottom:1px solid #dce1dd}p{margin:10px 0}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:14px;text-align:left;vertical-align:top;border-bottom:1px solid #cfd6d1;min-width:150px}th{background:#e9eeea}li{padding:6px 0}li p{font-size:14px;color:#59645e}@media(max-width:640px){main{padding:20px 16px}h1{font-size:27px}nav{gap:16px}}'''
(OUT/'philixa-stack-research.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Philixa stack research · 28 October 2026</title><style>'+css+'</style><main>'+body+'</main></html>',encoding='utf-8')
canvas='''import {Stack,Row,H1,H2,Text,Callout,Table,Button,Link,useHostTheme,useCanvasState} from 'cursor/canvas';
const data=DATA;
export default function Research(){
 const t=useHostTheme();const [view,setView]=useCanvasState('philixa-stack-research-view','Decision');
 return <Stack gap={18} style={{padding:24,color:t.text.primary,background:t.bg.editor,fontSize:14}}>
 <Text>PHILIXA / {data.date}</Text><H1>Work engine behind the chat</H1>
 <Callout tone="info" title="Research conclusion">Keep the existing backend. Add scoped native accounting context, a durable evidence loop and exception review. Choose the document model by evaluation, not brand claims.</Callout>
 <Row gap={8} wrap>{['Decision','Competitors','Stack','Source audit','Sources'].map(v=><Button key={v} onClick={()=>setView(v)}>{v}</Button>)}</Row>
 {view==='Decision'&&<><H2>Bill or chat → evidence → proposal → verified result</H2><Text>Read the relevant company, masters and historical transactions. Separate explicit facts, master data and historical suggestions. Resolve contradictions before asking the user for a short review.</Text><H2>Three priorities</H2><Text>1. Native Tally context and field provenance. 2. Multi-field messages and one compact proposal. 3. Checkpointed orchestration plus measured document extraction.</Text><H2>Budget-aware choice</H2><Text>Existing Groq baseline; 120B challenger. PyMuPDF plus one local layout parser first. PaddleOCR-VL or capped Mistral OCR evaluation only if needed. No model training prerequisite.</Text><H2>Honest boundary</H2><Text>A historical price does not establish this purchase’s actual price. A schema-valid answer can still be wrong. Vendor accuracy figures do not establish Philixa accuracy. Real-world automation remains unverified.</Text></>}
 {view==='Competitors'&&<><H2>Published workflow evidence</H2><Table headers={['Product','Published behaviour','What to learn']} rows={data.peers.map(p=>[p.name,p.facts,p.lesson])}/><Text>Vendor-described capabilities; no independent product trial. Exact framework/model stacks generally undisclosed. Vic.ai API provides concrete master/history/webhook evidence.</Text></>}
 {view==='Stack'&&<><H2>Project-specific recommendation</H2><Table headers={['Layer','Choice','Why / trade-off','Decision']} rows={data.stack}/><Text>Groq strict schemas and tool calling require separate stages according to current documentation. Local processing has hardware cost; paid OCR must be capped. No new provider was enabled.</Text></>}
 {view==='Source audit'&&<><H2>What the code currently proves</H2><Table headers={['Gap','Source evidence','Next change']} rows={data.gaps}/><Text>Source inspection on 28 October 2026; not a fresh browser/native acceptance run. Research did not modify application code or configuration.</Text></>}
 {view==='Sources'&&<><H2>Official sources</H2>{data.sources.map(s=><div key={s[0]}><Link href={s[2]}>{s[1]}</Link><Text>{s[3]}</Text></div>)}<Text>Full discussion and costs are in the companion HTML brief. No internal/private competitor implementation access; no measured winner on Indian GST bills.</Text></>}
 </Stack>;
}
'''.replace('DATA',json.dumps(data,ensure_ascii=False).replace('<','\\u003c'))
(OUT/'philixa-stack-research.canvas.tsx').write_text(canvas,encoding='utf-8')
assert all(k in body for k in ['id="overview"','id="competitors"','id="guidance"','id="sources"'])
assert len(peers)==5 and len(sources)==27 and len(stack)==10
print(json.dumps({'html':str(OUT/'philixa-stack-research.html'),'canvas':str(OUT/'philixa-stack-research.canvas.tsx'),'sources':len(sources),'peers':len(peers)},indent=2))
